                    Self::TypeParameter { .. } => 0,
                    Self::Nominal { arguments, .. } => {
                        arguments.len().checked_mul(size_of::<Self>())?
                    }
                    Self::Function { parameters, .. } => parameters
                        .len()
                        .checked_mul(size_of::<Self>())?
                        .checked_add(size_of::<Self>())?,
                    Self::Never
                    | Self::Unit
                    | Self::I64
                    | Self::I32
