                    | Self::I64
                    | Self::I32
                    | Self::Char
                    | Self::U8
                    | Self::Usize
                    | Self::ArrayU8(_)
                    | Self::F32
                    | Self::F64
                    | Self::Bool
                    | Self::String
                    | Self::Bytes
                    | Self::Str
